"""Data transformation pipeline."""

import re
import logging
from typing import Any, Callable, Dict, List, Optional

logger = logging.getLogger(__name__)

# Registry of named transforms
_transforms: Dict[str, Callable[[Dict[str, Any]], Optional[Dict[str, Any]]]] = {}


def register(name: str, fn: Callable[[Dict[str, Any]], Optional[Dict[str, Any]]]) -> None:
    """Register a named transform function."""
    _transforms[name] = fn


def get_transform(name: str) -> Optional[Callable[[Dict[str, Any]], Optional[Dict[str, Any]]]]:
    """Look up a registered transform by name."""
    return _transforms.get(name)


def apply_transforms(
    record_data: Optional[Dict[str, Any]], transform_names: List[str]
) -> Optional[Dict[str, Any]]:
    """Apply a list of named transforms to a record's data dict."""
    if record_data is None:
        return None
    current: Optional[Dict[str, Any]] = record_data
    for name in transform_names:
        fn = _transforms.get(name)
        if fn is None:
            logger.warning(f"Unknown transform: {name}")
            continue
        # Cast current to Dict[str, Any] since we checked it's not None above
        result = fn(current)  # type: ignore[arg-type]
        if result is None:
            return None  # filtered out
        current = result
    return current


def compose(*fns: Callable[[Dict[str, Any]], Optional[Dict[str, Any]]]) -> Callable[[Dict[str, Any]], Optional[Dict[str, Any]]]:
    """Compose multiple transform functions into a single function."""
    def composed(data: Dict[str, Any]) -> Optional[Dict[str, Any]]:
        current: Optional[Dict[str, Any]] = data
        for fn in fns:
            if current is None:
                return None
            current = fn(current)
        return current
    return composed


